<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForgePrintifyConnector\Preparation\{NativePortSchema,NativePortAdapter,ProtectedPanel,ExceptionReconciler,ReviewCoordinator,VersionedMutationHost,MutationFence};
require_once __DIR__.'/../fixtures/printify-connector/stage34/companion-test-bootstrap.php';
final class PrintifyCompanionBatch6Test extends TestCase {
 private function fixture():array{require_once __DIR__.'/../fixtures/printify-connector/batch6/SyntheticNativeCore.php';[$s]=(require __DIR__.'/../fixtures/printify-connector/batch5/fixture.php')();$core=new SyntheticNativeCore();return [$s,$core,new NativePortAdapter($core)];}
 public function testCanonicalSchemaAndAdaptersExist():void{self::assertTrue(class_exists(NativePortSchema::class));self::assertTrue(class_exists(NativePortAdapter::class));}
 public function testSchemaChecksManifestVersionsAndUnknownFields():void{[$s,$core]=$this->fixture();$m=$core->contractManifest();self::assertTrue(NativePortSchema::valid('manifest',$m));$m['secret']='no';self::assertFalse(NativePortSchema::valid('manifest',$m));unset($m['secret']);$m['contract_version']='2.0.0';self::assertFalse(NativePortSchema::valid('manifest',$m));}
 /** @dataProvider incompatibleFaults */
 public function testManifestFaultsDenyBeforeNativeCalls(string $fault):void{[$s,$core,$a]=$this->fixture();$core->fault=$fault;self::assertInstanceOf(WP_Error::class,$a->authorizeWorkflow($s,1,'inspect_reviews'));self::assertSame(0,$core->calls);}
 public static function incompatibleFaults():array{return array_map(static fn($x)=>[$x],['wrong_version','wrong_spec','missing_capability','extra_manifest']);}
 public function testTypedReviewAdaptersPreserveCoreAuthorityAndUnknownState():void{[$s,$core,$a]=$this->fixture();$core->operations->operationState='UNKNOWN';$w=new ReviewCoordinator($a);$q=$w->queue($s,1);self::assertIsArray($q);self::assertInstanceOf(WP_Error::class,$w->decide($s,1,$q['items'][0],'REVIEW_LOCAL','EVIDENCE_CHECKED'));self::assertSame('UNKNOWN',$w->decide($s,1,$q['items'][0],'ACKNOWLEDGE','UNCERTAINTY_RETAINED')['operation_state']);}
 public function testProtectedPanelRequiresActorSessionNonceScopeAndRechecksRevocation():void{[$s,$core,$a]=$this->fixture();$ctx=$core->context('publication');$panel=new ProtectedPanel($a);self::assertStringContainsString('PUBLICATION_PENDING',$panel->render($s,1,$ctx));$json=$panel->export($s,1,$ctx);self::assertIsString($json);self::assertStringNotContainsString($ctx['csrf_token'],$json);self::assertStringNotContainsString($ctx['session_fingerprint'],$json);$core->fault='revoked';self::assertInstanceOf(WP_Error::class,$panel->snapshot($s,1,$ctx));}
 /** @dataProvider invalidContext */
 public function testManipulatedPanelContextRejected(string $field,mixed $value):void{[$s,$core,$a]=$this->fixture();$c=$core->context('orders');$c[$field]=$value;self::assertInstanceOf(WP_Error::class,(new ProtectedPanel($a))->snapshot($s,1,$c));}
 public static function invalidContext():array{return [['view','execute'],['version','2.0.0'],['session_fingerprint',str_repeat('0',64)],['csrf_token','wrong-nonce'],['url','https://untrusted.test']];}
 public function testRecoveryReceiptCannotAcknowledgePendingDrain():void{[$s,$core,$a]=$this->fixture();$r=$a->recovery($s,1,['action'=>'INSPECT']);self::assertTrue($r['stop_all']);$core->emergency();self::assertGreaterThan($r['generation'],$a->recovery($s,1,['action'=>'INSPECT'])['generation']);$core->fault='false_drain_ack';self::assertInstanceOf(WP_Error::class,$a->recovery($s,1,['action'=>'INSPECT']));self::assertInstanceOf(WP_Error::class,$a->recovery($s,1,['action'=>'REARM']));}
 public function testAllocationReceiptRejectsWrongShopAndStaleAuthority():void{[$s,$core,$a]=$this->fixture();self::assertIsArray($a->allocation($s,1,['order_identity'=>str_repeat('a',64),'order_version'=>1]));foreach(['wrong_scope','revoked','stale_authority']as $fault){$core->fault=$fault;self::assertInstanceOf(WP_Error::class,$a->allocation($s,1,['order_identity'=>str_repeat('a',64),'order_version'=>1]));}}
 public function testMissingCoreAndJournalFailClosed():void{[$s,$core,$a]=$this->fixture();self::assertInstanceOf(WP_Error::class,(new NativePortAdapter())->authorizeWorkflow($s,1,'inspect_reviews'));$core->fault='missing_journal';self::assertInstanceOf(WP_Error::class,(new ReviewCoordinator($a))->queue($s,1));}
 public function testExceptionClassificationNeverChangesStateOrRetries():void{[$s,$core,$a]=$this->fixture();foreach(['CANCELLED'=>'CANCELLED_OBSERVATION','UNKNOWN'=>'UNCERTAIN','CONFLICTING'=>'CONFLICT']as $op=>$classification){$core->operations=new SyntheticOperationsCore();$core->operations->operationState=$op;$item=(new ReviewCoordinator($a))->queue($s,1)['items'][0];$r=ExceptionReconciler::classify($item);self::assertSame($classification,$r['classification']);self::assertSame($op,$r['operation_state']);self::assertFalse($r['retry_permitted']);self::assertFalse($r['external_execution_authorized']);}}
 public function testWrappedMutationPortPreservesOneShotFenceAndStopDenial():void{[$s,$core,$a]=$this->fixture();$core->safetyStop=false;$core->externalLock=false;$i=(require __DIR__.'/../fixtures/printify-connector/batch2/intent.php')();$f=new MutationFence(new VersionedMutationHost($a));self::assertIsArray($f->register($i));self::assertIsArray($f->reserve($i));self::assertInstanceOf(WP_Error::class,$f->reserve($i));$core->emergency();self::assertInstanceOf(WP_Error::class,(new VersionedMutationHost($a))->authorize($i));}
 public function testGetAdapterBindsOriginalIntentAndRejectsPrivateProjection():void{[$s,$core,$a]=$this->fixture();$core->safetyStop=false;$core->externalLock=false;$i=new DigiForge\Connector\Printify\ExternalOperationIntent(1,'personalized_pod',7,'SHOPS_READ',[],str_repeat('a',32));self::assertInstanceOf(DigiForge\Connector\Printify\ProviderResult::class,$a->read($i));$core->fault='get_private';self::assertInstanceOf(WP_Error::class,$a->read($i));$core->fault='';$core->emergency();self::assertInstanceOf(WP_Error::class,$a->read($i));}
 public function testAllPanelViewsAreFilteredByCoreAuthorizedScope():void{[$s,$core,$a]=$this->fixture();foreach(['publication'=>['PUBLICATION','PUBLICATION_PENDING'],'orders'=>['ORDER','ORDER_REVIEW'],'fulfillment'=>['FULFILLMENT','FULFILLMENT_REVIEW'],'conflicts'=>['ORDER','CONFLICTING'],'unknown'=>['ORDER','UNKNOWN']]as $view=>[$kind,$state]){$core->operations=new SyntheticOperationsCore();$core->operations->kind=$kind;$core->operations->operationState=$state;$m=(new ProtectedPanel($a))->snapshot($s,1,$core->context($view));self::assertCount(1,$m['items']);self::assertSame($state,$m['items'][0]['operation_state']);}}
 public function testEmergencyEventsAdvanceEvenWhileStopAlreadyOnAndStaleRecoveryNeverRearms():void{[$s,$core,$a]=$this->fixture();$core->emergency();$first=$a->recovery($s,1,['action'=>'INSPECT']);$core->emergency();$second=$a->recovery($s,1,['action'=>'INSPECT']);self::assertTrue($first['stop_all']);self::assertTrue($second['stop_all']);self::assertGreaterThan($first['generation'],$second['generation']);$core->fault='stale_recovery';$r=$a->recovery($s,1,['action'=>'INSPECT']);self::assertTrue($r['recovery_required']);self::assertFalse($r['external_execution_authorized']);}
 public function testSchemaRegistryAndEveryMethodReferenceAreBoundedAndKnown():void{$s=NativePortSchema::specification();self::assertSame('1.0.0',$s['version']);foreach($s['methods']as $method=>$rule){self::assertTrue(method_exists(DigiForgePrintifyConnector\Preparation\NativeCorePortInterface::class,$method),$method);self::assertNotEmpty($rule['semantic']);}self::assertFalse(NativePortSchema::valid('review_queue',['unexpected'=>'private']));$deep=[];for($n=0;$n<40;$n++)$deep=['nested'=>$deep];self::assertFalse(NativePortSchema::valid('json_object',$deep));}
 public function testRollbackAndTamperedJournalCannotProduceAdmission():void{[$s,$core,$a]=$this->fixture();$core->safetyStop=false;$core->externalLock=false;$i=(require __DIR__.'/../fixtures/printify-connector/batch2/intent.php')();$q=['contract_version'=>'1.0.0','action'=>'AUTHORIZE','binding'=>VersionedMutationHost::binding($i),'context'=>$i->context,'evidence_references'=>$i->evidenceReferences,'duplicate_key'=>$i->duplicateKey,'data'=>[]];foreach(['rollback_response','tampered_journal']as $fault){$core->fault=$fault;self::assertInstanceOf(WP_Error::class,$a->exchange($q));}}
 public function testUnknownExceptionCanNeverBeDowngradedByPartialShipment():void{[$s,$core,$a]=$this->fixture();[$scope,$o,$ship,$alloc,$ctx]=(require __DIR__.'/../fixtures/printify-connector/batch5/fixture.php')();$model=DigiForgePrintifyConnector\Preparation\ShipmentReadModel::fromProvider($scope,$o,$ship,$alloc,$ctx);$item=$core->operations->reviewQueue($scope,1,20)['items'][0];$item['kind']='FULFILLMENT';$item['subject_hash']=$model->jsonSerialize()['order_identity'];$item['operation_state']='UNKNOWN';self::assertSame('UNCERTAIN',ExceptionReconciler::classify($item,$model)['classification']);}

 public function testNativeAdapterConcurrentReservationsHaveOneDurableWinner():void{[$s,$core]=$this->fixture();require_once __DIR__.'/../fixtures/printify-connector/batch2/DurableSyntheticMutationCore.php';$path=tempnam(sys_get_temp_dir(),'df-native-claim-');unlink($path);try{$core->mutation=new DurableSyntheticMutationCore($path);$core->safetyStop=false;$core->externalLock=false;$i=(require __DIR__.'/../fixtures/printify-connector/batch2/intent.php')();$f=new MutationFence(new VersionedMutationHost(new NativePortAdapter($core)));self::assertIsArray($f->register($i));$children=[];for($n=0;$n<2;$n++){$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/../fixtures/printify-connector/batch6/claim-worker.php',$path],[1=>['pipe','w'],2=>['pipe','w']],$pipes);self::assertIsResource($p);$children[]=[$p,$pipes];}$wins=0;foreach($children as [$p,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);self::assertSame(0,proc_close($p),$out.$err);$wins+=(int)$out;}self::assertSame(1,$wins);}finally{foreach(['','.lock','.tmp']as $suffix)@unlink($path.$suffix);}}
 public function testMalformedRegisterCannotBecomeArbitraryStateOrHttpProxy():void{[$s,$core,$a]=$this->fixture();$i=(require __DIR__.'/../fixtures/printify-connector/batch2/intent.php')();$q=['contract_version'=>'1.0.0','action'=>'REGISTER','binding'=>VersionedMutationHost::binding($i),'context'=>$i->context,'evidence_references'=>$i->evidenceReferences,'duplicate_key'=>$i->duplicateKey,'data'=>['prepared'=>['scope_fingerprint'=>$i->scope->fingerprint(),'request'=>['method'=>'DELETE','path'=>'https://untrusted.test','body'=>[]]]]];self::assertInstanceOf(WP_Error::class,$a->exchange($q));self::assertSame(0,$core->calls);}

 public function testStopAndExternalLockEachDenyNativeAdmission():void{[$s,$core,$a]=$this->fixture();$i=(require __DIR__.'/../fixtures/printify-connector/batch2/intent.php')();foreach([[true,false],[false,true],[true,true]]as [$stop,$lock]){$core->safetyStop=$stop;$core->externalLock=$lock;self::assertInstanceOf(WP_Error::class,(new VersionedMutationHost($a))->authorize($i));}}

}
